package vn.codegym;import java.sql.*;import java.util.*;public class UserDao{private Connection open()throws SQLException{return DriverManager.getConnection("jdbc:mysql://localhost:3306/user_management","root","password");}public List<User> all()throws SQLException{List<User> list=new ArrayList<>();try(Connection c=open();PreparedStatement p=c.prepareStatement("SELECT * FROM users ORDER BY id");ResultSet r=p.executeQuery()){while(r.next())list.add(new User(r.getInt("id"),r.getString("name"),r.getString("email"),r.getString("country")));}return list;}public void save(User u)throws SQLException{String sql=u.id()==0?"INSERT INTO users(name,email,country) VALUES(?,?,?)":"UPDATE users SET name=?,email=?,country=? WHERE id=?";try(Connection c=open();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,u.name());p.setString(2,u.email());p.setString(3,u.country());if(u.id()!=0)p.setInt(4,u.id());p.executeUpdate();}}public void delete(int id)throws SQLException{try(Connection c=open();PreparedStatement p=c.prepareStatement("DELETE FROM users WHERE id=?")){p.setInt(1,id);p.executeUpdate();}}}
